/** All-or-nothing. The UPDATE is the check; there is no separate read to
 *  race against. affectedRows tells us whether we won. */
Optional<Hold> hold(String showId, List<String> seatIds, User user, Duration ttl) {
    String holdId = UUID.randomUUID().toString();
    Instant expiresAt = Instant.now().plus(ttl);

    int claimed = jdbc.update("""
        UPDATE show_seats
           SET status = 'HELD', held_by = ?, hold_expires_at = ?
         WHERE show_id = ? AND seat_id IN (?)
           AND (status = 'AVAILABLE'
                OR (status = 'HELD' AND hold_expires_at < now()))
        """, holdId, expiresAt, showId, seatIds);

    if (claimed != seatIds.size()) {
        // Someone got at least one of them first. Roll the partial claim back
        // so we never leave a user holding three of the five they asked for.
        releaseByHold(holdId);
        return Optional.empty();
    }
    return Optional.of(new Hold(holdId, seatIds, expiresAt));
}
